INSERT INTO "equipment" ("slug", "nameEs", "nameEn") VALUES
('kettlebell', 'Pesa rusa (kettlebell)', 'Kettlebell'),
('resistance_band', 'Banda elástica', 'Resistance band'),
('cable_machine', 'Máquina de poleas', 'Cable machine'),
('treadmill', 'Cinta de correr', 'Treadmill'),
('elliptical', 'Elíptica', 'Elliptical trainer'),
('rowing_machine', 'Remo ergómetro', 'Rowing machine'),
('leg_press', 'Prensa de piernas', 'Leg press machine'),
('jump_rope', 'Soga para saltar', 'Jump rope'),
('stability_ball', 'Pelota de estabilidad (fitball)', 'Stability ball'),
('medicine_ball', 'Pelota medicinal', 'Medicine ball')
INSERT INTO "exercises" ("slug", "muscle", "measure", "met", "baseMinutes", "baseReps", "secondsPerRep", "loadFactor", "highImpact", "nameEs", "nameEn", "instructionsEs", "instructionsEn") VALUES
('dumbbell_lunge', 'legs', 'reps_weight', 4.5, NULL, 10, 3, 0.12, false, 'Estocadas con mancuernas', 'Dumbbell lunges', 'Con una mancuerna en cada mano, da un paso al frente y baja hasta que ambas rodillas formen 90°. Alterna.', 'Holding a dumbbell in each hand, step forward and lower until both knees reach 90°. Alternate legs.'),
('dumbbell_calf_raise', 'legs', 'reps_weight', 3.0, NULL, 15, 2, 0.15, false, 'Elevación de talones con mancuernas', 'Dumbbell calf raise', 'De pie con las mancuernas a los lados, sube a puntas de pie y baja despacio.', 'Standing with dumbbells at your sides, rise onto your toes and lower slowly.'),
('dumbbell_shrug', 'back', 'reps_weight', 3.0, NULL, 15, 2, 0.2, false, 'Encogimientos con mancuernas', 'Dumbbell shrug', 'Con los brazos extendidos, eleva los hombros hacia las orejas, sostén un segundo y baja.', 'With arms straight, raise your shoulders toward your ears, hold for a second and lower.'),
('arnold_press', 'shoulders', 'reps_weight', 4.5, NULL, 10, 3, 0.12, false, 'Press Arnold', 'Arnold press', 'Empieza con las mancuernas frente al pecho y las palmas hacia ti; rota mientras empujas hacia arriba.', 'Start with the dumbbells in front of your chest, palms facing you; rotate as you press overhead.'),
('dumbbell_upright_row', 'shoulders', 'reps_weight', 3.5, NULL, 12, 3, 0.1, false, 'Remo al mentón con mancuernas', 'Dumbbell upright row', 'Sube las mancuernas pegadas al cuerpo hasta el pecho, con los codos por encima de las manos.', 'Raise the dumbbells close to your body up to your chest, elbows higher than your hands.'),
('dumbbell_side_bend', 'abs', 'reps_weight', 3.0, NULL, 12, 2, 0.15, false, 'Inclinación lateral con mancuerna', 'Dumbbell side bend', 'Con una mancuerna en una mano, inclina el torso hacia ese lado y vuelve usando el oblicuo contrario.', 'With a dumbbell in one hand, bend sideways toward it and return using the opposite oblique.'),
('front_squat', 'legs', 'reps_weight', 6.0, NULL, 8, 4, 0.5, false, 'Sentadilla frontal', 'Front squat', 'Con la barra apoyada delante de los hombros y los codos altos, baja en sentadilla manteniendo el torso erguido.', 'With the bar resting on the front of your shoulders and elbows high, squat down keeping your torso upright.'),
('barbell_lunge', 'legs', 'reps_weight', 5.5, NULL, 10, 3, 0.35, false, 'Estocadas con barra', 'Barbell lunges', 'Con la barra sobre la espalda, da un paso al frente y baja controlando. Alterna las piernas.', 'With the bar on your back, step forward and lower under control. Alternate legs.'),
('good_morning', 'glutes', 'reps_weight', 4.5, NULL, 10, 4, 0.3, false, 'Buenos días con barra', 'Good morning', 'Con la barra sobre la espalda y rodillas apenas flexionadas, inclina el torso llevando la cadera atrás y vuelve.', 'With the bar on your back and knees slightly bent, hinge forward pushing your hips back, then return.'),
('sumo_deadlift', 'glutes', 'reps_weight', 6.0, NULL, 8, 4, 0.8, false, 'Peso muerto sumo', 'Sumo deadlift', 'Con los pies bien abiertos y las manos por dentro de las rodillas, levanta la barra extendiendo cadera y rodillas.', 'With a wide stance and hands inside your knees, lift the bar by extending hips and knees.'),
('barbell_shrug', 'back', 'reps_weight', 3.5, NULL, 12, 2, 0.6, false, 'Encogimientos con barra', 'Barbell shrug', 'Con la barra frente a los muslos, eleva los hombros hacia las orejas y baja controlando.', 'With the bar in front of your thighs, raise your shoulders toward your ears and lower under control.'),
('barbell_upright_row', 'shoulders', 'reps_weight', 4.0, NULL, 10, 3, 0.3, false, 'Remo al mentón con barra', 'Barbell upright row', 'Sube la barra pegada al cuerpo hasta el pecho con los codos altos y baja despacio.', 'Raise the bar close to your body to chest height with elbows high and lower slowly.'),
('close_grip_bench_press', 'triceps', 'reps_weight', 5.0, NULL, 10, 3, 0.45, false, 'Press de banca agarre cerrado', 'Close-grip bench press', 'Acostado en el banco, toma la barra con las manos al ancho de los hombros y empuja con los codos pegados.', 'Lying on the bench, grip the bar shoulder-width apart and press with elbows tucked in.'),
('barbell_lying_triceps_extension', 'triceps', 'reps_weight', 3.5, NULL, 10, 3, 0.25, false, 'Extensión de tríceps acostado con barra', 'Barbell lying triceps extension', 'Acostado con la barra arriba, flexiona solo los codos llevándola hacia la frente y vuelve a extender.', 'Lying with the bar overhead, bend only your elbows to lower it toward your forehead and extend back.'),
('reverse_barbell_curl', 'biceps', 'reps_weight', 3.5, NULL, 12, 3, 0.2, false, 'Curl inverso con barra', 'Reverse barbell curl', 'Toma la barra con las palmas hacia abajo y flexiona los codos sin despegarlos del cuerpo.', 'Grip the bar palms down and curl it up without moving your elbows away from your body.'),
('drag_curl', 'biceps', 'reps_weight', 3.5, NULL, 10, 3, 0.22, false, 'Curl arrastrado con barra', 'Barbell drag curl', 'Sube la barra rozando el torso llevando los codos hacia atrás, y baja por el mismo camino.', 'Raise the bar dragging it along your torso while pulling your elbows back, then lower the same way.'),
('barbell_calf_raise', 'legs', 'reps_weight', 3.5, NULL, 15, 2, 0.5, false, 'Elevación de talones con barra', 'Barbell calf raise', 'Con la barra sobre la espalda, sube a puntas de pie y baja despacio.', 'With the bar on your back, rise onto your toes and lower slowly.'),
('push_press', 'shoulders', 'reps_weight', 6.0, NULL, 8, 3, 0.4, false, 'Push press', 'Push press', 'Flexiona apenas las rodillas y usa el impulso de las piernas para empujar la barra sobre la cabeza.', 'Dip slightly at the knees and use the leg drive to press the bar overhead.'),
('barbell_glute_bridge', 'glutes', 'reps_weight', 4.5, NULL, 12, 3, 0.5, false, 'Puente de glúteos con barra', 'Barbell glute bridge', 'Acostado con la barra sobre la cadera, eleva la pelvis apretando los glúteos y baja controlando.', 'Lying with the bar across your hips, drive your pelvis up squeezing your glutes and lower under control.'),
('bulgarian_split_squat', 'legs', 'reps', 5.0, NULL, 10, 3, NULL, false, 'Sentadilla búlgara', 'Bulgarian split squat', 'Apoya el empeine de atrás sobre el banco y baja con la pierna de adelante hasta 90°. Cambia de pierna.', 'Rest your rear foot on the bench and lower on your front leg to 90°. Switch legs.'),
('bench_box_jump', 'legs', 'reps', 8.0, NULL, 8, 4, NULL, true, 'Salto al banco', 'Bench box jump', 'Desde una media sentadilla, salta al banco cayendo suave con las rodillas flexionadas y baja caminando.', 'From a half squat, jump onto the bench landing softly with bent knees, then step down.'),
('decline_push_up', 'chest', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Flexiones declinadas', 'Decline push-up', 'Con los pies sobre el banco y las manos en el suelo, baja el pecho y empuja manteniendo el cuerpo recto.', 'With your feet on the bench and hands on the floor, lower your chest and push up keeping your body straight.'),
('bench_hip_thrust', 'glutes', 'reps', 4.0, NULL, 15, 3, NULL, false, 'Hip thrust en banco', 'Bench hip thrust', 'Con la espalda alta apoyada en el banco, empuja la cadera hacia arriba hasta alinearla con el torso.', 'With your upper back on the bench, drive your hips up until they line up with your torso.'),
('single_leg_hip_thrust', 'glutes', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Hip thrust a una pierna', 'Single-leg hip thrust', 'Como el hip thrust en banco, pero con una pierna extendida en el aire. Cambia de lado.', 'Like the bench hip thrust but with one leg extended in the air. Switch sides.'),
('bench_knee_tuck', 'abs', 'reps', 3.5, NULL, 15, 2, NULL, false, 'Encogimiento de rodillas en banco', 'Bench knee tuck', 'Sentado en el borde del banco, inclínate atrás y lleva las rodillas al pecho; luego extiende las piernas.', 'Sitting on the edge of the bench, lean back and pull your knees to your chest, then extend your legs.'),
('bench_leg_raise', 'abs', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Elevación de piernas en banco', 'Bench leg raise', 'Acostado en el banco, sujétate atrás de la cabeza y eleva las piernas estiradas hasta la vertical.', 'Lying on the bench, hold on behind your head and raise your straight legs to vertical.'),
('step_up_knee_drive', 'glutes', 'reps', 6.5, NULL, 10, 3, NULL, false, 'Subida al banco con rodilla arriba', 'Step-up with knee drive', 'Sube al banco y, al llegar arriba, eleva la rodilla contraria hasta la cadera. Baja y alterna.', 'Step up onto the bench and drive the opposite knee up to hip height at the top. Step down and alternate.'),
('lateral_step_up', 'legs', 'reps', 6.0, NULL, 10, 3, NULL, false, 'Subida lateral al banco', 'Lateral step-up', 'De costado al banco, sube con la pierna más cercana y baja controlando. Cambia de lado.', 'Standing sideways to the bench, step up with the near leg and lower under control. Switch sides.'),
('bench_reverse_hyper', 'glutes', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Hiperextensión inversa en banco', 'Bench reverse hyperextension', 'Boca abajo con la cadera en el borde del banco, eleva las piernas estiradas hasta la horizontal y baja.', 'Face down with your hips at the edge of the bench, raise your straight legs to horizontal and lower.'),
('feet_elevated_bench_dip', 'triceps', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Fondos con pies elevados', 'Feet-elevated bench dip', 'Con las manos en un banco y los pies en otro, baja flexionando los codos y sube extendiéndolos.', 'With hands on one bench and feet on another, lower by bending your elbows and push back up.'),
('incline_mountain_climber', 'abs', 'time', 7.0, 2, NULL, 3, NULL, true, 'Escaladores con manos en banco', 'Incline mountain climbers', 'Con las manos en el banco y el cuerpo recto, lleva las rodillas al pecho alternando rápido.', 'With your hands on the bench and body straight, drive your knees to your chest alternating quickly.'),
('bench_box_squat', 'legs', 'reps', 5.0, NULL, 12, 3, NULL, false, 'Sentadilla al banco', 'Bench box squat', 'Baja en sentadilla hasta rozar el banco con los glúteos y sube sin sentarte del todo.', 'Squat down until your glutes touch the bench and stand up without fully sitting.'),
('bench_pike_push_up', 'shoulders', 'reps', 4.0, NULL, 8, 3, NULL, false, 'Flexiones en pica con pies en banco', 'Feet-elevated pike push-up', 'Con los pies en el banco y la cadera alta, baja la cabeza hacia el suelo flexionando los codos y empuja.', 'With your feet on the bench and hips high, lower your head toward the floor bending your elbows, then push.'),
('decline_plank', 'abs', 'time', 3.8, 1, NULL, 3, NULL, false, 'Plancha con pies en banco', 'Decline plank', 'Apoya los antebrazos en el suelo y los pies en el banco. Mantén el cuerpo recto y el abdomen firme.', 'Rest your forearms on the floor and your feet on the bench. Keep your body straight and abs tight.'),
('bench_lateral_hops', 'general', 'time', 8.0, 2, NULL, 3, NULL, true, 'Saltos laterales sobre el banco', 'Bench lateral hops', 'Apoya las manos en el banco y salta de un lado al otro con los pies juntos.', 'Place your hands on the bench and hop your feet from side to side together.'),
('bench_aerobic_steps', 'general', 'time', 5.5, 8, NULL, 3, NULL, false, 'Pasos aeróbicos en banco', 'Bench aerobic steps', 'Sube y baja del banco a ritmo constante alternando el pie que sube primero.', 'Step up and down the bench at a steady pace, alternating the leading foot.'),
('wall_sit', 'legs', 'time', 3.5, 1, NULL, 3, NULL, false, 'Sentadilla isométrica en pared', 'Wall sit', 'Apoya la espalda en la pared y baja hasta que los muslos queden paralelos al suelo. Mantén la posición.', 'Lean your back against a wall and slide down until your thighs are parallel to the floor. Hold.'),
('bodyweight_calf_raise', 'legs', 'reps', 2.8, NULL, 20, 2, NULL, false, 'Elevación de talones', 'Calf raise', 'De pie, sube a puntas de pie lo más alto posible y baja despacio.', 'Standing, rise onto your toes as high as you can and lower slowly.'),
('side_plank', 'abs', 'time', 3.5, 1, NULL, 3, NULL, false, 'Plancha lateral', 'Side plank', 'Apoya un antebrazo y el costado de los pies, eleva la cadera y mantén el cuerpo recto. Cambia de lado.', 'Rest on one forearm and the side of your feet, lift your hips and keep your body straight. Switch sides.'),
('bike_recovery', 'general', 'time', 4.0, 15, NULL, 3, NULL, false, 'Bici fija suave (recuperación)', 'Easy recovery ride', 'Pedalea sin resistencia y a ritmo cómodo, pudiendo hablar sin esfuerzo.', 'Pedal with no resistance at a comfortable pace, able to talk easily.'),
('bike_intervals', 'general', 'time', 8.5, 20, NULL, 3, NULL, false, 'Bici fija por intervalos', 'Bike intervals', 'Alterna 1 minuto fuerte con 2 minutos suaves durante todo el tiempo.', 'Alternate 1 hard minute with 2 easy minutes throughout.'),
('bike_hill_climb', 'legs', 'time', 8.0, 15, NULL, 3, NULL, false, 'Bici fija: subida sentado', 'Seated hill climb', 'Sube la resistencia hasta que cueste pedalear y mantén una cadencia lenta y constante sentado.', 'Increase resistance until pedaling is hard and keep a slow, steady seated cadence.'),
('bike_standing_climb', 'legs', 'time', 9.0, 8, NULL, 3, NULL, false, 'Bici fija: subida de pie', 'Standing climb', 'Con resistencia alta, pedalea de pie con el torso inclinado y las manos en el manubrio.', 'With high resistance, pedal standing with your torso leaning forward and hands on the handlebar.'),
('bike_sprints', 'legs', 'time', 10.5, 10, NULL, 3, NULL, false, 'Bici fija: sprints', 'Bike sprints', 'Haz 20 segundos a máxima velocidad y 40 segundos suaves, repitiendo.', 'Do 20 seconds all-out and 40 seconds easy, repeating.'),
('bike_tempo', 'general', 'time', 7.5, 20, NULL, 3, NULL, false, 'Bici fija a ritmo sostenido', 'Tempo ride', 'Pedalea a un ritmo exigente pero sostenible, con la respiración agitada.', 'Pedal at a challenging but sustainable pace, breathing hard.'),
('bike_high_cadence', 'legs', 'time', 7.0, 10, NULL, 3, NULL, false, 'Bici fija: cadencia alta', 'High-cadence drills', 'Con resistencia baja, pedalea lo más rápido posible manteniendo la cadera quieta en el asiento.', 'With low resistance, pedal as fast as you can keeping your hips still on the seat.'),
('bike_pyramid', 'general', 'time', 8.0, 20, NULL, 3, NULL, false, 'Bici fija en pirámide', 'Pyramid ride', 'Sube la resistencia cada 2 minutos hasta el máximo y luego bájala de a poco.', 'Increase resistance every 2 minutes to your max, then bring it back down gradually.'),
('bike_endurance', 'general', 'time', 6.8, 30, NULL, 3, NULL, false, 'Bici fija de resistencia', 'Endurance ride', 'Pedalea a ritmo moderado y constante durante un tiempo prolongado.', 'Pedal at a moderate, steady pace for an extended time.'),
('bike_tabata', 'general', 'time', 10.0, 4, NULL, 3, NULL, false, 'Bici fija Tabata', 'Bike Tabata', 'Ocho rondas de 20 segundos a máxima intensidad con 10 segundos de descanso.', 'Eight rounds of 20 seconds all-out with 10 seconds of rest.'),
('bike_single_leg', 'legs', 'time', 6.0, 8, NULL, 3, NULL, false, 'Bici fija a una pierna', 'Single-leg pedaling', 'Pedalea con una sola pierna 1 minuto y cambia, para trabajar la técnica del pedaleo completo.', 'Pedal with one leg for 1 minute then switch, to work on a full pedal stroke.'),
('bike_low_cadence_strength', 'legs', 'time', 7.5, 12, NULL, 3, NULL, false, 'Bici fija de fuerza (cadencia baja)', 'Low-cadence strength ride', 'Resistencia muy alta y cadencia lenta, empujando con fuerza cada pedalada.', 'Very high resistance and a slow cadence, pushing hard on every stroke.'),
('bike_warm_up', 'general', 'time', 4.5, 8, NULL, 3, NULL, false, 'Bici fija: entrada en calor', 'Bike warm-up', 'Pedalea suave aumentando de a poco el ritmo para preparar el cuerpo.', 'Pedal easily, gradually increasing the pace to get your body ready.'),
('bike_cool_down', 'general', 'time', 3.5, 6, NULL, 3, NULL, false, 'Bici fija: vuelta a la calma', 'Bike cool-down', 'Pedalea muy suave bajando el ritmo hasta recuperar la respiración.', 'Pedal very easily, slowing down until your breathing recovers.'),
('bike_fartlek', 'general', 'time', 8.0, 20, NULL, 3, NULL, false, 'Bici fija fartlek', 'Bike fartlek', 'Cambia libremente entre ritmos suaves, medios y fuertes según cómo te sientas.', 'Freely switch between easy, moderate and hard efforts as you feel.'),
('bike_heavy_seated', 'glutes', 'time', 7.8, 12, NULL, 3, NULL, false, 'Bici fija: subida pesada sentado', 'Heavy seated climb', 'Resistencia alta sentado, empujando desde el talón para activar los glúteos.', 'High resistance while seated, pushing through your heels to engage the glutes.'),
('bike_race_simulation', 'general', 'time', 9.0, 15, NULL, 3, NULL, false, 'Bici fija: simulación de carrera', 'Race simulation ride', 'Combina tramos llanos, subidas de pie y sprints finales como en una carrera.', 'Combine flat stretches, standing climbs and final sprints like a race.'),
('bike_spin_class', 'general', 'time', 8.5, 30, NULL, 3, NULL, false, 'Clase de spinning', 'Spin class', 'Sigue una sesión guiada alternando ritmos, resistencias y posiciones.', 'Follow a guided session alternating paces, resistances and positions.'),
('bike_steady_moderate', 'general', 'time', 6.8, 20, NULL, 3, NULL, false, 'Bici fija moderada', 'Steady moderate ride', 'Pedalea a ritmo moderado y parejo, con la respiración algo agitada.', 'Pedal at a moderate, even pace, breathing somewhat hard.'),
('wide_grip_pull_up', 'back', 'reps', 8.0, NULL, 6, 3, NULL, false, 'Dominadas agarre ancho', 'Wide-grip pull-up', 'Toma la barra bien abierta con las palmas al frente y sube llevando el pecho hacia la barra.', 'Grip the bar wide with palms forward and pull your chest toward the bar.'),
('neutral_grip_pull_up', 'back', 'reps', 8.0, NULL, 6, 3, NULL, false, 'Dominadas agarre neutro', 'Neutral-grip pull-up', 'Con las palmas enfrentadas, sube hasta que el mentón pase la barra y baja controlando.', 'With palms facing each other, pull up until your chin clears the bar and lower under control.'),
('negative_pull_up', 'back', 'reps', 6.0, NULL, 5, 5, NULL, false, 'Dominadas negativas', 'Negative pull-up', 'Empieza arriba (ayúdate con un salto) y baja lo más lento posible, 4 a 5 segundos.', 'Start at the top (jump to get there) and lower as slowly as possible, 4 to 5 seconds.'),
('scapular_pull_up', 'back', 'reps', 4.0, NULL, 10, 2, NULL, false, 'Dominadas escapulares', 'Scapular pull-up', 'Colgado con los brazos estirados, junta y baja los omóplatos para subir unos centímetros sin flexionar los codos.', 'Hanging with straight arms, squeeze your shoulder blades down to rise a few inches without bending your elbows.'),
('dead_hang', 'back', 'time', 3.0, 0.5, NULL, 3, NULL, false, 'Colgarse de la barra', 'Dead hang', 'Cuélgate de la barra con los brazos estirados y el cuerpo relajado, respirando con calma.', 'Hang from the bar with straight arms and a relaxed body, breathing calmly.'),
('commando_pull_up', 'back', 'reps', 8.0, NULL, 6, 3, NULL, false, 'Dominadas comando', 'Commando pull-up', 'Toma la barra con las manos una delante de la otra y sube llevando la cabeza a un lado y al otro.', 'Grip the bar with one hand in front of the other and pull up bringing your head to alternate sides.'),
('archer_pull_up', 'back', 'reps', 8.5, NULL, 4, 3, NULL, false, 'Dominadas arquero', 'Archer pull-up', 'Con agarre muy ancho, sube hacia una mano mientras el otro brazo queda casi estirado. Alterna.', 'With a very wide grip, pull toward one hand while the other arm stays nearly straight. Alternate.'),
('typewriter_pull_up', 'back', 'reps', 8.5, NULL, 4, 4, NULL, false, 'Dominadas máquina de escribir', 'Typewriter pull-up', 'Sube y, arriba, desplázate de una mano a la otra a lo largo de la barra antes de bajar.', 'Pull up and, at the top, shift from one hand to the other along the bar before lowering.'),
('hanging_knee_raise', 'abs', 'reps', 4.0, NULL, 12, 3, NULL, false, 'Elevación de rodillas colgado', 'Hanging knee raise', 'Colgado de la barra, lleva las rodillas al pecho sin balancearte y baja despacio.', 'Hanging from the bar, bring your knees to your chest without swinging and lower slowly.'),
('toes_to_bar', 'abs', 'reps', 5.0, NULL, 8, 3, NULL, false, 'Pies a la barra', 'Toes to bar', 'Colgado, eleva las piernas estiradas hasta tocar la barra con los pies y baja controlando.', 'Hanging, raise your straight legs until your feet touch the bar and lower under control.'),
('hanging_oblique_knee_raise', 'abs', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Elevación de rodillas oblicua colgado', 'Hanging oblique knee raise', 'Colgado, sube las rodillas hacia un costado y luego hacia el otro.', 'Hanging, raise your knees toward one side, then the other.'),
('windshield_wipers', 'abs', 'reps', 5.0, NULL, 6, 4, NULL, false, 'Limpiaparabrisas colgado', 'Hanging windshield wipers', 'Colgado con las piernas arriba, llévalas de lado a lado como un limpiaparabrisas. Avanzado.', 'Hanging with your legs up, sweep them side to side like a windshield wiper. Advanced.'),
('l_sit_hang', 'abs', 'time', 4.0, 0.5, NULL, 3, NULL, false, 'Colgado en L', 'Hanging L-sit', 'Colgado de la barra, sostén las piernas estiradas a la altura de la cadera formando una L.', 'Hanging from the bar, hold your straight legs at hip height forming an L.'),
('close_grip_chin_up', 'biceps', 'reps', 8.0, NULL, 6, 3, NULL, false, 'Dominadas supinas agarre cerrado', 'Close-grip chin-up', 'Con las manos juntas y las palmas hacia ti, sube hasta pasar el mentón y baja completo.', 'With hands close together and palms facing you, pull up past your chin and lower fully.'),
('chin_up_hold', 'biceps', 'time', 5.0, 0.5, NULL, 3, NULL, false, 'Isometría en dominada supina', 'Chin-up hold', 'Sube a la posición alta de la dominada supina y mantenla con el mentón sobre la barra.', 'Pull up to the top of a chin-up and hold with your chin above the bar.'),
('pull_up_knee_raise', 'abs', 'reps', 8.0, NULL, 5, 4, NULL, false, 'Dominada con elevación de rodillas', 'Pull-up with knee raise', 'Sube en dominada mientras llevas las rodillas al pecho y baja todo junto.', 'Pull up while bringing your knees to your chest and lower everything together.'),
('hanging_shrug', 'back', 'reps', 4.0, NULL, 10, 2, NULL, false, 'Encogimientos colgado', 'Hanging shrug', 'Colgado con los brazos estirados, eleva y baja el cuerpo solo moviendo los hombros.', 'Hanging with straight arms, raise and lower your body by moving only your shoulders.'),
('kb_swing', 'glutes', 'reps_weight', 9.8, NULL, 15, 2, 0.15, false, 'Swing con pesa rusa', 'Kettlebell swing', 'Lleva la pesa entre las piernas con la cadera atrás y empuja la cadera para balancearla a la altura del pecho.', 'Hike the kettlebell between your legs with hips back and snap your hips to swing it to chest height.'),
('kb_goblet_squat', 'legs', 'reps_weight', 5.0, NULL, 12, 3, 0.15, false, 'Sentadilla goblet con pesa rusa', 'Kettlebell goblet squat', 'Sostén la pesa por las asas frente al pecho y baja en sentadilla con el torso erguido.', 'Hold the kettlebell by the horns in front of your chest and squat with an upright torso.'),
('kb_deadlift', 'glutes', 'reps_weight', 5.0, NULL, 12, 4, 0.25, false, 'Peso muerto con pesa rusa', 'Kettlebell deadlift', 'Con la pesa entre los pies, tómala con la espalda recta y levántate extendiendo la cadera.', 'With the kettlebell between your feet, grab it with a straight back and stand by extending your hips.'),
('kb_single_leg_deadlift', 'glutes', 'reps_weight', 4.5, NULL, 10, 4, 0.12, false, 'Peso muerto a una pierna con pesa rusa', 'Single-leg kettlebell deadlift', 'Con la pesa en una mano, inclínate llevando la pierna contraria atrás hasta quedar en T y vuelve.', 'Holding the kettlebell in one hand, hinge forward lifting the opposite leg back into a T, then return.'),
('kb_clean', 'back', 'reps_weight', 7.0, NULL, 8, 3, 0.12, false, 'Cargada con pesa rusa', 'Kettlebell clean', 'Desde el balanceo entre las piernas, lleva la pesa a la posición de rack junto al hombro con un tirón de cadera.', 'From a backswing between your legs, bring the kettlebell to the rack position at your shoulder with a hip drive.'),
('kb_press', 'shoulders', 'reps_weight', 5.0, NULL, 10, 3, 0.12, false, 'Press con pesa rusa', 'Kettlebell press', 'Desde la posición de rack, empuja la pesa sobre la cabeza hasta extender el brazo. Cambia de lado.', 'From the rack position, press the kettlebell overhead until your arm is straight. Switch sides.'),
('kb_snatch', 'shoulders', 'reps_weight', 9.5, NULL, 8, 3, 0.1, true, 'Arranque con pesa rusa', 'Kettlebell snatch', 'Desde el balanceo, lleva la pesa directamente sobre la cabeza en un solo movimiento explosivo.', 'From the backswing, bring the kettlebell straight overhead in one explosive movement.'),
('kb_row', 'back', 'reps_weight', 5.0, NULL, 12, 3, 0.2, false, 'Remo con pesa rusa', 'Kettlebell row', 'Inclinado con la espalda recta, tira la pesa hacia la cadera llevando el codo atrás.', 'Hinged forward with a straight back, pull the kettlebell to your hip driving the elbow back.'),
('kb_halo', 'shoulders', 'reps_weight', 3.5, NULL, 8, 4, 0.08, false, 'Halo con pesa rusa', 'Kettlebell halo', 'Sostén la pesa por las asas y hazla girar alrededor de la cabeza, en ambos sentidos.', 'Hold the kettlebell by the horns and circle it around your head in both directions.'),
('kb_russian_twist', 'abs', 'reps_weight', 4.0, NULL, 16, 2, 0.08, false, 'Giro ruso con pesa rusa', 'Kettlebell Russian twist', 'Sentado con el torso inclinado atrás, lleva la pesa de un lado al otro de la cadera.', 'Seated with your torso leaning back, move the kettlebell from one side of your hips to the other.'),
('kb_windmill', 'abs', 'reps_weight', 4.0, NULL, 8, 4, 0.08, false, 'Molino con pesa rusa', 'Kettlebell windmill', 'Con la pesa arriba, inclínate de costado bajando la mano libre hacia el pie sin dejar de mirar la pesa.', 'With the kettlebell overhead, bend sideways lowering your free hand toward your foot while looking at the kettlebell.'),
('kb_turkish_get_up', 'general', 'reps_weight', 5.0, NULL, 3, 15, 0.08, false, 'Levantamiento turco', 'Turkish get-up', 'Desde acostado con la pesa arriba, ponte de pie paso a paso sin bajar el brazo y vuelve al suelo.', 'From lying down with the kettlebell overhead, stand up step by step without lowering your arm, then return.'),
('kb_lunge', 'legs', 'reps_weight', 4.5, NULL, 10, 3, 0.12, false, 'Estocadas con pesa rusa', 'Kettlebell lunges', 'Con la pesa frente al pecho, da un paso atrás y baja hasta 90°. Alterna.', 'Holding the kettlebell at your chest, step back and lower to 90°. Alternate.'),
('kb_sumo_squat', 'glutes', 'reps_weight', 5.0, NULL, 12, 3, 0.2, false, 'Sentadilla sumo con pesa rusa', 'Kettlebell sumo squat', 'Con los pies bien abiertos y la pesa colgando entre las piernas, baja en sentadilla y sube.', 'With a wide stance and the kettlebell hanging between your legs, squat down and stand back up.'),
('kb_high_pull', 'shoulders', 'reps_weight', 7.0, NULL, 10, 3, 0.15, false, 'Tirón alto con pesa rusa', 'Kettlebell high pull', 'Desde la cadera inclinada, tira la pesa hacia el mentón con los codos altos usando el impulso de la cadera.', 'From a hip hinge, pull the kettlebell to your chin with elbows high, using hip drive.'),
('kb_floor_press', 'chest', 'reps_weight', 4.0, NULL, 10, 3, 0.12, false, 'Press de pecho en el suelo con pesa rusa', 'Kettlebell floor press', 'Acostado en el suelo, empuja la pesa hacia arriba hasta extender el brazo y baja hasta apoyar el codo.', 'Lying on the floor, press the kettlebell up until your arm is straight and lower until your elbow touches.'),
('kb_curl', 'biceps', 'reps_weight', 3.5, NULL, 12, 3, 0.08, false, 'Curl con pesa rusa', 'Kettlebell curl', 'Sostén la pesa por el asa con los codos pegados y flexiona los brazos.', 'Hold the kettlebell by the handle with elbows tucked and curl it up.'),
('kb_overhead_extension', 'triceps', 'reps_weight', 3.5, NULL, 12, 3, 0.1, false, 'Extensión de tríceps con pesa rusa', 'Kettlebell overhead extension', 'Sostén la pesa con ambas manos sobre la cabeza, bájala detrás de la nuca y vuelve a extender.', 'Hold the kettlebell with both hands overhead, lower it behind your head and extend back up.'),
('kb_farmer_walk', 'general', 'time', 6.0, 2, NULL, 3, NULL, false, 'Caminata del granjero', 'Farmer''s walk', 'Camina erguido con una pesa en cada mano, los hombros atrás y el abdomen firme.', 'Walk tall with a kettlebell in each hand, shoulders back and abs tight.'),
('kb_figure_eight', 'abs', 'reps_weight', 5.0, NULL, 10, 3, 0.1, false, 'Ocho con pesa rusa', 'Kettlebell figure eight', 'En media sentadilla, pasa la pesa entre las piernas dibujando un ocho de una mano a la otra.', 'In a half squat, pass the kettlebell between your legs in a figure eight from hand to hand.'),
('band_squat', 'legs', 'reps', 4.0, NULL, 15, 3, NULL, false, 'Sentadilla con banda', 'Banded squat', 'Pisa la banda y sostén los extremos a la altura de los hombros; baja en sentadilla y sube.', 'Stand on the band holding the ends at shoulder height; squat down and stand back up.'),
('band_lateral_walk', 'glutes', 'reps', 3.5, NULL, 12, 2, NULL, false, 'Caminata lateral con banda', 'Banded lateral walk', 'Con la banda sobre las rodillas y en media sentadilla, da pasos laterales sin juntar los pies.', 'With the band above your knees in a half squat, take side steps without bringing your feet together.'),
('band_glute_kickback', 'glutes', 'reps', 3.0, NULL, 15, 2, NULL, false, 'Patada de glúteo con banda', 'Banded glute kickback', 'En cuatro apoyos con la banda en el pie, empuja la pierna hacia atrás y arriba. Cambia de lado.', 'On all fours with the band around your foot, push your leg back and up. Switch sides.'),
('band_clamshell', 'glutes', 'reps', 2.8, NULL, 15, 2, NULL, false, 'Almeja con banda', 'Banded clamshell', 'Acostado de lado con las rodillas flexionadas y la banda arriba de ellas, abre la rodilla de arriba sin mover la cadera.', 'Lying on your side with knees bent and the band above them, open your top knee without moving your hips.'),
('band_pull_apart', 'back', 'reps', 3.0, NULL, 15, 2, NULL, false, 'Separación de banda', 'Band pull-apart', 'Con los brazos al frente, separa la banda llevando las manos hacia los costados y junta los omóplatos.', 'With your arms in front, pull the band apart bringing your hands out to the sides and squeeze your shoulder blades.'),
('band_row', 'back', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Remo con banda', 'Banded row', 'Sentado con la banda alrededor de los pies, tira de los extremos hacia el abdomen llevando los codos atrás.', 'Seated with the band around your feet, pull the ends toward your stomach driving your elbows back.'),
('band_lat_pulldown', 'back', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Jalón al pecho con banda', 'Banded lat pulldown', 'Con la banda anclada arriba, tira hacia abajo llevando los codos a los costados del cuerpo.', 'With the band anchored high, pull down bringing your elbows to your sides.'),
('band_chest_press', 'chest', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Press de pecho con banda', 'Banded chest press', 'Con la banda pasando por la espalda, empuja los extremos al frente hasta extender los brazos.', 'With the band around your back, press the ends forward until your arms are straight.'),
('band_chest_fly', 'chest', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Aperturas con banda', 'Banded chest fly', 'Con la banda anclada detrás, lleva los brazos casi estirados desde los costados hacia el frente.', 'With the band anchored behind you, bring your nearly straight arms from the sides to the front.'),
('band_curl', 'biceps', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Curl de bíceps con banda', 'Banded biceps curl', 'Pisa la banda y flexiona los codos llevando las manos hacia los hombros.', 'Stand on the band and bend your elbows bringing your hands toward your shoulders.'),
('band_hammer_curl', 'biceps', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Curl martillo con banda', 'Banded hammer curl', 'Como el curl con banda, pero con las palmas enfrentadas.', 'Like the banded curl, but with palms facing each other.'),
('band_triceps_pushdown', 'triceps', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Extensión de tríceps hacia abajo con banda', 'Banded triceps pushdown', 'Con la banda anclada arriba, empuja hacia abajo extendiendo los codos sin separarlos del cuerpo.', 'With the band anchored high, push down extending your elbows without moving them away from your body.'),
('band_overhead_extension', 'triceps', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Extensión de tríceps sobre la cabeza con banda', 'Banded overhead triceps extension', 'Pisa la banda detrás de ti y extiende los brazos por encima de la cabeza.', 'Stand on the band behind you and extend your arms overhead.'),
('band_shoulder_press', 'shoulders', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Press de hombros con banda', 'Banded shoulder press', 'Pisa la banda y empuja los extremos desde los hombros hasta arriba de la cabeza.', 'Stand on the band and press the ends from your shoulders to overhead.'),
('band_lateral_raise', 'shoulders', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Elevaciones laterales con banda', 'Banded lateral raise', 'Pisa la banda y eleva los brazos hacia los costados hasta la altura de los hombros.', 'Stand on the band and raise your arms out to the sides to shoulder height.'),
('band_face_pull', 'shoulders', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Face pull con banda', 'Banded face pull', 'Con la banda anclada a la altura de la cara, tira hacia ti separando las manos y llevando los codos altos.', 'With the band anchored at face height, pull toward you separating your hands with elbows high.'),
('band_deadlift', 'glutes', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Peso muerto con banda', 'Banded deadlift', 'Pisa la banda, inclínate con la espalda recta y levántate extendiendo la cadera.', 'Stand on the band, hinge with a straight back and stand by extending your hips.'),
('band_good_morning', 'glutes', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Buenos días con banda', 'Banded good morning', 'Pisa la banda y pásala por detrás del cuello; inclina el torso llevando la cadera atrás y vuelve.', 'Stand on the band and loop it behind your neck; hinge forward pushing your hips back and return.'),
('band_pallof_press', 'abs', 'reps', 3.0, NULL, 12, 4, NULL, false, 'Press Pallof con banda', 'Banded Pallof press', 'De costado al anclaje, empuja la banda al frente desde el pecho sin dejar que el torso gire.', 'Standing sideways to the anchor, press the band forward from your chest without letting your torso rotate.'),
('band_woodchop', 'abs', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Leñador con banda', 'Banded woodchop', 'Con la banda anclada arriba a un lado, llévala en diagonal hacia la rodilla contraria girando el torso.', 'With the band anchored high to one side, pull it diagonally toward the opposite knee while rotating your torso.'),
('cable_lat_pulldown', 'back', 'reps_weight', 4.5, NULL, 12, 3, 0.45, false, 'Jalón al pecho en polea', 'Cable lat pulldown', 'Sentado, toma la barra ancha y tira hacia el pecho llevando los codos hacia abajo y atrás.', 'Seated, grab the wide bar and pull it to your chest driving your elbows down and back.'),
('cable_seated_row', 'back', 'reps_weight', 4.5, NULL, 12, 3, 0.45, false, 'Remo sentado en polea', 'Seated cable row', 'Sentado con la espalda recta, tira del agarre hacia el abdomen y vuelve estirando los brazos.', 'Seated with a straight back, pull the handle to your stomach and return by straightening your arms.'),
('cable_straight_arm_pulldown', 'back', 'reps_weight', 3.5, NULL, 12, 3, 0.2, false, 'Pullover de pie en polea', 'Straight-arm cable pulldown', 'De pie e inclinado, baja la barra con los brazos casi estirados hasta los muslos.', 'Standing and leaning forward, pull the bar down to your thighs with nearly straight arms.'),
('cable_reverse_fly', 'back', 'reps_weight', 3.0, NULL, 12, 3, 0.06, false, 'Aperturas inversas en polea', 'Cable reverse fly', 'Con las poleas cruzadas a la altura del pecho, abre los brazos hacia atrás juntando los omóplatos.', 'With crossed cables at chest height, open your arms back squeezing your shoulder blades.'),
('cable_crossover', 'chest', 'reps_weight', 3.5, NULL, 12, 3, 0.12, false, 'Cruce de poleas', 'Cable crossover', 'Con las poleas altas, lleva las manos hacia abajo y al frente hasta cruzarlas a la altura de la cadera.', 'With the pulleys high, bring your hands down and forward until they cross at hip height.'),
('cable_chest_press', 'chest', 'reps_weight', 4.0, NULL, 12, 3, 0.2, false, 'Press de pecho en polea', 'Cable chest press', 'De espaldas a la máquina, empuja los agarres al frente hasta extender los brazos.', 'With your back to the machine, press the handles forward until your arms are straight.'),
('cable_triceps_pushdown', 'triceps', 'reps_weight', 3.5, NULL, 12, 3, 0.25, false, 'Extensión de tríceps en polea', 'Cable triceps pushdown', 'Con la barra en la polea alta, empuja hacia abajo extendiendo los codos sin moverlos.', 'With the bar on the high pulley, push down extending your elbows without moving them.'),
('cable_rope_pushdown', 'triceps', 'reps_weight', 3.5, NULL, 12, 3, 0.2, false, 'Extensión de tríceps con cuerda', 'Cable rope pushdown', 'Con la cuerda en la polea alta, empuja hacia abajo separando los extremos al final.', 'With the rope on the high pulley, push down and spread the ends apart at the bottom.'),
('cable_overhead_extension', 'triceps', 'reps_weight', 3.5, NULL, 12, 3, 0.15, false, 'Extensión de tríceps sobre la cabeza en polea', 'Cable overhead triceps extension', 'De espaldas a la polea, extiende los brazos por encima de la cabeza llevando la cuerda al frente.', 'Facing away from the pulley, extend your arms overhead bringing the rope forward.'),
('cable_curl', 'biceps', 'reps_weight', 3.5, NULL, 12, 3, 0.2, false, 'Curl de bíceps en polea', 'Cable biceps curl', 'Con la barra en la polea baja, flexiona los codos llevándola hacia el pecho.', 'With the bar on the low pulley, curl it toward your chest.'),
('cable_hammer_curl', 'biceps', 'reps_weight', 3.5, NULL, 12, 3, 0.18, false, 'Curl martillo con cuerda', 'Cable rope hammer curl', 'Con la cuerda en la polea baja y las palmas enfrentadas, flexiona los codos.', 'With the rope on the low pulley and palms facing each other, curl up.'),
('cable_face_pull', 'shoulders', 'reps_weight', 3.0, NULL, 15, 3, 0.15, false, 'Face pull en polea', 'Cable face pull', 'Con la cuerda a la altura de la cara, tira hacia ti separando las manos y con los codos altos.', 'With the rope at face height, pull toward you separating your hands with elbows high.'),
('cable_lateral_raise', 'shoulders', 'reps_weight', 3.0, NULL, 12, 3, 0.05, false, 'Elevación lateral en polea', 'Cable lateral raise', 'De costado a la polea baja, eleva el brazo hacia el costado hasta la altura del hombro.', 'Standing sideways to the low pulley, raise your arm out to the side to shoulder height.'),
('cable_front_raise', 'shoulders', 'reps_weight', 3.0, NULL, 12, 3, 0.06, false, 'Elevación frontal en polea', 'Cable front raise', 'De espaldas a la polea baja, eleva el agarre al frente hasta la altura de los hombros.', 'Facing away from the low pulley, raise the handle in front of you to shoulder height.'),
('cable_upright_row', 'shoulders', 'reps_weight', 3.5, NULL, 12, 3, 0.2, false, 'Remo al mentón en polea', 'Cable upright row', 'Con la barra en la polea baja, súbela pegada al cuerpo hasta el pecho con los codos altos.', 'With the bar on the low pulley, raise it close to your body to chest height with elbows high.'),
('cable_crunch', 'abs', 'reps_weight', 3.5, NULL, 15, 3, 0.25, false, 'Crunch de rodillas en polea', 'Kneeling cable crunch', 'De rodillas frente a la polea alta, con la cuerda junto a la cabeza, enrolla el torso hacia el suelo.', 'Kneeling facing the high pulley with the rope by your head, curl your torso toward the floor.'),
('cable_woodchop', 'abs', 'reps_weight', 4.0, NULL, 12, 3, 0.15, false, 'Leñador en polea', 'Cable woodchop', 'Con la polea alta a un lado, tira en diagonal hacia la rodilla contraria rotando el torso.', 'With the pulley high to one side, pull diagonally toward the opposite knee while rotating your torso.'),
('cable_pallof_press', 'abs', 'reps_weight', 3.0, NULL, 12, 4, 0.1, false, 'Press Pallof en polea', 'Cable Pallof press', 'De costado a la polea, empuja el agarre al frente desde el pecho sin dejar que el torso gire.', 'Standing sideways to the pulley, press the handle forward from your chest without letting your torso rotate.'),
('cable_glute_kickback', 'glutes', 'reps_weight', 3.5, NULL, 12, 3, 0.08, false, 'Patada de glúteo en polea', 'Cable glute kickback', 'Con la tobillera en la polea baja, lleva la pierna estirada hacia atrás apretando el glúteo.', 'With the ankle strap on the low pulley, push your straight leg back squeezing the glute.'),
('cable_pull_through', 'glutes', 'reps_weight', 4.0, NULL, 12, 4, 0.3, false, 'Pull-through en polea', 'Cable pull-through', 'De espaldas a la polea baja con la cuerda entre las piernas, empuja la cadera al frente hasta quedar erguido.', 'Facing away from the low pulley with the rope between your legs, drive your hips forward until upright.'),
('treadmill_walk', 'general', 'time', 3.5, 20, NULL, 3, NULL, false, 'Caminata en cinta', 'Treadmill walk', 'Camina a ritmo cómodo (unos 4–5 km/h) con la espalda erguida, sin sujetarte de las barandas.', 'Walk at a comfortable pace (about 2.5–3 mph) with an upright back, without holding the rails.'),
('treadmill_brisk_walk', 'general', 'time', 4.3, 20, NULL, 3, NULL, false, 'Caminata rápida en cinta', 'Brisk treadmill walk', 'Camina a paso rápido (unos 6 km/h) balanceando los brazos.', 'Walk briskly (about 3.7 mph) swinging your arms.'),
('treadmill_incline_walk', 'legs', 'time', 6.0, 20, NULL, 3, NULL, false, 'Caminata en pendiente', 'Incline treadmill walk', 'Camina con la cinta inclinada al 8–12 % a ritmo moderado, con el torso apenas inclinado.', 'Walk with an 8–12 % incline at a moderate pace, torso slightly forward.'),
('treadmill_jog', 'general', 'time', 7.0, 20, NULL, 3, NULL, true, 'Trote en cinta', 'Treadmill jog', 'Trota a ritmo suave (unos 8 km/h), apoyando el pie debajo de la cadera.', 'Jog at an easy pace (about 5 mph), landing with your foot under your hips.'),
('treadmill_run', 'general', 'time', 9.8, 20, NULL, 3, NULL, true, 'Carrera en cinta', 'Treadmill run', 'Corre a ritmo sostenido (unos 10 km/h) con los brazos relajados.', 'Run at a steady pace (about 6 mph) with relaxed arms.'),
('treadmill_intervals', 'general', 'time', 10.0, 20, NULL, 3, NULL, true, 'Intervalos en cinta', 'Treadmill intervals', 'Alterna 1 minuto corriendo rápido con 2 minutos caminando o trotando suave.', 'Alternate 1 minute of fast running with 2 minutes of walking or easy jogging.'),
('treadmill_hill_intervals', 'legs', 'time', 9.0, 15, NULL, 3, NULL, true, 'Intervalos en subida', 'Treadmill hill intervals', 'Alterna 1 minuto trotando con pendiente alta y 1 minuto caminando sin pendiente.', 'Alternate 1 minute jogging on a steep incline with 1 minute walking flat.'),
('treadmill_sprints', 'general', 'time', 11.5, 10, NULL, 3, NULL, true, 'Sprints en cinta', 'Treadmill sprints', 'Haz 20–30 segundos a máxima velocidad y descansa caminando 1 minuto. Repite.', 'Do 20–30 seconds at top speed and recover walking for 1 minute. Repeat.'),
('treadmill_walk_run', 'general', 'time', 7.5, 20, NULL, 3, NULL, true, 'Caminar y trotar en cinta', 'Treadmill walk-run', 'Alterna 2 minutos caminando con 1 minuto trotando. Ideal para empezar a correr.', 'Alternate 2 minutes walking with 1 minute jogging. Great for starting to run.'),
('treadmill_backward_walk', 'legs', 'time', 4.0, 8, NULL, 3, NULL, false, 'Caminata hacia atrás en cinta', 'Backward treadmill walk', 'Con la cinta muy lenta y sujetándote de la baranda, camina hacia atrás con pasos cortos.', 'With the belt very slow and holding the rail, walk backward with short steps.'),
('treadmill_side_shuffle', 'legs', 'time', 6.0, 4, NULL, 3, NULL, true, 'Desplazamiento lateral en cinta', 'Treadmill side shuffle', 'Con la cinta lenta, colócate de costado y desplázate lateralmente sin cruzar los pies. Cambia de lado.', 'With the belt slow, turn sideways and shuffle without crossing your feet. Switch sides.'),
('treadmill_walking_lunges', 'legs', 'time', 5.0, 5, NULL, 3, NULL, false, 'Estocadas caminando en cinta', 'Treadmill walking lunges', 'Con la cinta muy lenta e inclinada, avanza con estocadas largas y controladas.', 'With the belt very slow and inclined, move forward with long, controlled lunges.'),
('treadmill_power_walk_incline', 'glutes', 'time', 6.5, 15, NULL, 3, NULL, false, 'Caminata de potencia en pendiente', 'Incline power walk', 'Camina rápido con pendiente alta empujando con el talón para activar los glúteos.', 'Walk fast on a steep incline pushing through your heels to engage your glutes.'),
('treadmill_recovery_walk', 'general', 'time', 3.0, 10, NULL, 3, NULL, false, 'Caminata de recuperación', 'Recovery walk', 'Camina lento y relajado para recuperar la respiración entre esfuerzos.', 'Walk slowly and relaxed to recover your breathing between efforts.'),
('treadmill_tempo_run', 'general', 'time', 10.5, 15, NULL, 3, NULL, true, 'Carrera a ritmo umbral', 'Tempo run', 'Corre a un ritmo exigente pero sostenible durante todo el tiempo.', 'Run at a challenging but sustainable pace for the whole time.'),
('treadmill_fartlek', 'general', 'time', 9.0, 20, NULL, 3, NULL, true, 'Fartlek en cinta', 'Treadmill fartlek', 'Cambia la velocidad libremente entre trote suave, medio y rápido.', 'Change speed freely between easy, moderate and fast running.'),
('treadmill_progressive', 'general', 'time', 9.0, 20, NULL, 3, NULL, true, 'Carrera progresiva', 'Progressive run', 'Empieza trotando suave y sube la velocidad cada 3–4 minutos hasta terminar rápido.', 'Start with an easy jog and increase the speed every 3–4 minutes, finishing fast.'),
('treadmill_12_3_30', 'glutes', 'time', 6.5, 30, NULL, 3, NULL, false, 'Caminata 12-3-30', '12-3-30 treadmill walk', 'Camina 30 minutos con 12 % de pendiente a unos 5 km/h, sin sujetarte de las barandas.', 'Walk for 30 minutes at a 12 % incline and about 3 mph, without holding the rails.'),
('treadmill_warm_up', 'general', 'time', 3.5, 5, NULL, 3, NULL, false, 'Cinta: entrada en calor', 'Treadmill warm-up', 'Camina suave aumentando el ritmo de a poco durante algunos minutos.', 'Walk easily, gradually increasing the pace for a few minutes.'),
('treadmill_cool_down', 'general', 'time', 3.0, 5, NULL, 3, NULL, false, 'Cinta: vuelta a la calma', 'Treadmill cool-down', 'Baja la velocidad y camina relajado hasta normalizar la respiración.', 'Slow down and walk relaxed until your breathing returns to normal.'),
('elliptical_easy', 'general', 'time', 4.5, 20, NULL, 3, NULL, false, 'Elíptica suave', 'Easy elliptical', 'Pedalea en la elíptica con resistencia baja y movimiento fluido de brazos y piernas.', 'Stride on the elliptical with low resistance and smooth arm and leg movement.'),
('elliptical_moderate', 'general', 'time', 5.5, 20, NULL, 3, NULL, false, 'Elíptica moderada', 'Moderate elliptical', 'Mantén un ritmo moderado con resistencia media, empujando y tirando de los manubrios.', 'Keep a moderate pace with medium resistance, pushing and pulling the handles.'),
('elliptical_intervals', 'general', 'time', 7.5, 20, NULL, 3, NULL, false, 'Elíptica por intervalos', 'Elliptical intervals', 'Alterna 1 minuto rápido con 2 minutos suaves.', 'Alternate 1 fast minute with 2 easy minutes.'),
('elliptical_high_resistance', 'legs', 'time', 7.0, 15, NULL, 3, NULL, false, 'Elíptica con resistencia alta', 'High-resistance elliptical', 'Sube la resistencia y pedalea más lento empujando fuerte con las piernas.', 'Increase the resistance and stride slower, pushing hard with your legs.'),
('elliptical_reverse', 'glutes', 'time', 5.5, 10, NULL, 3, NULL, false, 'Elíptica hacia atrás', 'Reverse elliptical', 'Pedalea en sentido inverso para cargar más los glúteos y los isquiotibiales.', 'Stride in reverse to put more work on your glutes and hamstrings.'),
('elliptical_no_hands', 'abs', 'time', 5.5, 10, NULL, 3, NULL, false, 'Elíptica sin manos', 'No-hands elliptical', 'Suelta los manubrios y mantén el equilibrio con el abdomen firme y la espalda erguida.', 'Let go of the handles and keep your balance with tight abs and an upright back.'),
('elliptical_arms_focus', 'shoulders', 'time', 5.5, 10, NULL, 3, NULL, false, 'Elíptica con énfasis en brazos', 'Arm-focused elliptical', 'Empuja y tira de los manubrios con fuerza, dejando que las piernas acompañen suave.', 'Push and pull the handles hard, letting your legs follow lightly.'),
('elliptical_hill_program', 'legs', 'time', 7.0, 20, NULL, 3, NULL, false, 'Elíptica: programa de colinas', 'Elliptical hill program', 'Usa el programa de colinas o sube y baja la inclinación cada 2 minutos.', 'Use the hill program or raise and lower the incline every 2 minutes.'),
('elliptical_tabata', 'general', 'time', 9.0, 4, NULL, 3, NULL, false, 'Elíptica Tabata', 'Elliptical Tabata', 'Ocho rondas de 20 segundos a máxima intensidad con 10 segundos suaves.', 'Eight rounds of 20 seconds all-out with 10 easy seconds.'),
('elliptical_pyramid', 'general', 'time', 7.0, 20, NULL, 3, NULL, false, 'Elíptica en pirámide', 'Elliptical pyramid', 'Sube la resistencia cada 2 minutos hasta el máximo y luego bájala de a poco.', 'Increase resistance every 2 minutes to your max, then bring it back down gradually.'),
('elliptical_steady_long', 'general', 'time', 5.5, 35, NULL, 3, NULL, false, 'Elíptica continua larga', 'Long steady elliptical', 'Mantén un ritmo moderado y constante durante una sesión prolongada.', 'Keep a moderate, steady pace for an extended session.'),
('elliptical_warm_up', 'general', 'time', 4.0, 6, NULL, 3, NULL, false, 'Elíptica: entrada en calor', 'Elliptical warm-up', 'Empieza suave y aumenta el ritmo de a poco.', 'Start easy and gradually pick up the pace.'),
('elliptical_cool_down', 'general', 'time', 3.5, 6, NULL, 3, NULL, false, 'Elíptica: vuelta a la calma', 'Elliptical cool-down', 'Baja la resistencia y el ritmo hasta recuperar la respiración.', 'Lower the resistance and pace until your breathing recovers.'),
('elliptical_fartlek', 'general', 'time', 7.0, 20, NULL, 3, NULL, false, 'Elíptica fartlek', 'Elliptical fartlek', 'Varía el ritmo libremente entre suave, medio y fuerte.', 'Vary the pace freely between easy, moderate and hard.'),
('elliptical_high_cadence', 'general', 'time', 7.0, 10, NULL, 3, NULL, false, 'Elíptica de cadencia alta', 'High-cadence elliptical', 'Con resistencia baja, mueve las piernas lo más rápido posible manteniendo el control.', 'With low resistance, move your legs as fast as you can while staying in control.'),
('elliptical_glute_focus', 'glutes', 'time', 6.0, 15, NULL, 3, NULL, false, 'Elíptica para glúteos', 'Glute-focused elliptical', 'Inclina apenas el torso atrás y empuja desde los talones con resistencia media-alta.', 'Lean back slightly and push through your heels with medium-high resistance.'),
('elliptical_tempo', 'general', 'time', 7.0, 15, NULL, 3, NULL, false, 'Elíptica a ritmo sostenido', 'Tempo elliptical', 'Mantén un ritmo exigente pero sostenible durante todo el tiempo.', 'Hold a challenging but sustainable pace throughout.'),
('elliptical_recovery', 'general', 'time', 4.0, 10, NULL, 3, NULL, false, 'Elíptica de recuperación', 'Recovery elliptical', 'Movimiento suave y relajado, ideal entre días de entrenamiento intenso.', 'Easy, relaxed movement, ideal between hard training days.'),
('elliptical_endurance', 'general', 'time', 6.0, 30, NULL, 3, NULL, false, 'Elíptica de resistencia', 'Endurance elliptical', 'Sostén un ritmo moderado durante mucho tiempo controlando la respiración.', 'Sustain a moderate pace for a long time while controlling your breathing.'),
('elliptical_sprint', 'general', 'time', 9.0, 8, NULL, 3, NULL, false, 'Sprints en elíptica', 'Elliptical sprints', 'Haz 30 segundos a máxima velocidad y 90 segundos suaves, repitiendo.', 'Do 30 seconds at top speed and 90 easy seconds, repeating.'),
('row_steady', 'back', 'time', 7.0, 20, NULL, 3, NULL, false, 'Remo continuo', 'Steady rowing', 'Rema a ritmo moderado: empuja con las piernas, inclina el torso atrás y tira del manubrio al abdomen.', 'Row at a moderate pace: drive with your legs, lean back and pull the handle to your stomach.'),
('row_intervals', 'general', 'time', 8.5, 20, NULL, 3, NULL, false, 'Remo por intervalos', 'Rowing intervals', 'Alterna 1 minuto fuerte con 1 minuto suave.', 'Alternate 1 hard minute with 1 easy minute.'),
('row_sprints', 'general', 'time', 10.0, 10, NULL, 3, NULL, false, 'Sprints de remo', 'Rowing sprints', 'Haz 20 paladas a máxima potencia y descansa 1 minuto remando suave. Repite.', 'Do 20 strokes at max power and recover with 1 minute of easy rowing. Repeat.'),
('row_technique_drill', 'back', 'time', 4.8, 8, NULL, 3, NULL, false, 'Remo: técnica por partes', 'Rowing technique drill', 'Practica la secuencia piernas, torso, brazos y vuelve en orden inverso, despacio.', 'Practice the sequence legs, body, arms and return in reverse order, slowly.'),
('row_arms_only', 'back', 'time', 4.5, 5, NULL, 3, NULL, false, 'Remo solo con brazos', 'Arms-only rowing', 'Con las piernas estiradas y el torso fijo, tira solo con los brazos.', 'With straight legs and a still torso, pull with your arms only.'),
('row_pyramid', 'general', 'time', 8.0, 20, NULL, 3, NULL, false, 'Remo en pirámide', 'Rowing pyramid', 'Rema 1, 2, 3, 2 y 1 minutos fuertes con 1 minuto suave entre cada uno.', 'Row 1, 2, 3, 2 and 1 hard minutes with 1 easy minute between each.'),
('row_long_endurance', 'general', 'time', 7.0, 30, NULL, 3, NULL, false, 'Remo largo de resistencia', 'Long endurance row', 'Rema a ritmo cómodo y constante durante una sesión prolongada.', 'Row at a comfortable, steady pace for an extended session.'),
('row_tabata', 'general', 'time', 10.0, 4, NULL, 3, NULL, false, 'Remo Tabata', 'Rowing Tabata', 'Ocho rondas de 20 segundos a máxima intensidad con 10 segundos de pausa.', 'Eight rounds of 20 seconds all-out with 10 seconds of rest.'),
('row_power_strokes', 'back', 'time', 9.0, 8, NULL, 3, NULL, false, 'Paladas de potencia', 'Power strokes', 'Rema a ritmo bajo pero con la máxima fuerza en cada palada.', 'Row at a low stroke rate but with maximum force on every stroke.'),
('row_low_rate', 'back', 'time', 6.5, 15, NULL, 3, NULL, false, 'Remo a ritmo bajo', 'Low stroke rate rowing', 'Mantén unas 20 paladas por minuto cuidando la técnica y la fuerza de las piernas.', 'Hold about 20 strokes per minute focusing on technique and leg drive.'),
('row_high_rate', 'general', 'time', 8.5, 10, NULL, 3, NULL, false, 'Remo a ritmo alto', 'High stroke rate rowing', 'Rema a más de 28 paladas por minuto sin perder la secuencia.', 'Row at over 28 strokes per minute without losing the sequence.'),
('row_warm_up', 'general', 'time', 4.8, 5, NULL, 3, NULL, false, 'Remo: entrada en calor', 'Rowing warm-up', 'Rema suave aumentando de a poco la intensidad.', 'Row easily, gradually increasing the intensity.'),
('row_cool_down', 'general', 'time', 4.0, 5, NULL, 3, NULL, false, 'Remo: vuelta a la calma', 'Rowing cool-down', 'Rema muy suave hasta recuperar la respiración.', 'Row very easily until your breathing recovers.'),
('row_500m_repeats', 'general', 'time', 9.0, 15, NULL, 3, NULL, false, 'Repeticiones de 500 m', '500 m repeats', 'Rema 500 metros fuerte y descansa 2 minutos remando suave. Repite.', 'Row 500 meters hard and rest 2 minutes rowing easily. Repeat.'),
('row_2k_test', 'general', 'time', 9.5, 8, NULL, 3, NULL, false, 'Test de 2000 m', '2K row test', 'Rema 2000 metros lo más rápido que puedas manteniendo un ritmo parejo.', 'Row 2,000 meters as fast as you can holding an even pace.'),
('row_legs_back', 'back', 'time', 5.5, 5, NULL, 3, NULL, false, 'Remo con piernas y torso', 'Legs-and-back rowing', 'Rema sin flexionar los brazos: solo piernas y balanceo del torso.', 'Row without bending your arms: legs and torso swing only.'),
('row_pause_drill', 'back', 'time', 5.5, 8, NULL, 3, NULL, false, 'Remo con pausa', 'Pause rowing drill', 'Haz una pausa de un segundo con los brazos estirados antes de cada palada.', 'Pause for one second with straight arms before each stroke.'),
('row_fartlek', 'general', 'time', 8.0, 20, NULL, 3, NULL, false, 'Remo fartlek', 'Rowing fartlek', 'Varía la intensidad libremente durante la sesión.', 'Vary the intensity freely during the session.'),
('row_progressive', 'general', 'time', 8.0, 20, NULL, 3, NULL, false, 'Remo progresivo', 'Progressive row', 'Empieza suave y aumenta la intensidad cada 4 minutos.', 'Start easy and increase the intensity every 4 minutes.'),
('row_recovery', 'general', 'time', 4.5, 10, NULL, 3, NULL, false, 'Remo de recuperación', 'Recovery row', 'Rema suave y relajado, ideal después de un día exigente.', 'Row easily and relaxed, ideal after a hard day.'),
('leg_press', 'legs', 'reps_weight', 5.0, NULL, 12, 3, 1.0, false, 'Prensa de piernas', 'Leg press', 'Con los pies al ancho de la cadera, baja la plataforma hasta 90° de rodilla y empuja sin bloquear las rodillas.', 'With feet hip-width apart, lower the platform to 90° at the knee and push without locking your knees.'),
('leg_press_wide', 'glutes', 'reps_weight', 5.0, NULL, 12, 3, 1.0, false, 'Prensa con pies abiertos', 'Wide-stance leg press', 'Coloca los pies más abiertos que la cadera y con las puntas hacia afuera para trabajar glúteos y aductores.', 'Place your feet wider than your hips with toes out to work glutes and adductors.'),
('leg_press_narrow', 'legs', 'reps_weight', 5.0, NULL, 12, 3, 0.9, false, 'Prensa con pies juntos', 'Narrow-stance leg press', 'Con los pies juntos en el centro de la plataforma, baja controlando y empuja.', 'With your feet close together in the middle of the platform, lower under control and push.'),
('leg_press_high_feet', 'glutes', 'reps_weight', 5.0, NULL, 12, 3, 1.0, false, 'Prensa con pies altos', 'High-feet leg press', 'Con los pies en la parte alta de la plataforma, empuja desde los talones.', 'With your feet high on the platform, push through your heels.'),
('leg_press_low_feet', 'legs', 'reps_weight', 5.0, NULL, 12, 3, 0.8, false, 'Prensa con pies bajos', 'Low-feet leg press', 'Con los pies en la parte baja de la plataforma, enfocado en los cuádriceps. Controla la bajada.', 'With your feet low on the platform, focusing on the quads. Control the descent.'),
('single_leg_press', 'legs', 'reps_weight', 5.0, NULL, 10, 3, 0.5, false, 'Prensa a una pierna', 'Single-leg press', 'Empuja con una sola pierna, con la otra apoyada en el costado. Cambia de pierna.', 'Push with one leg only, resting the other to the side. Switch legs.'),
('leg_press_calf_raise', 'legs', 'reps_weight', 3.5, NULL, 15, 2, 1.0, false, 'Gemelos en prensa', 'Leg press calf raise', 'Con las piernas estiradas y solo la punta de los pies en la plataforma, empuja con los tobillos.', 'With straight legs and only the balls of your feet on the platform, push with your ankles.'),
('leg_press_pause', 'legs', 'reps_weight', 5.0, NULL, 10, 5, 0.85, false, 'Prensa con pausa', 'Paused leg press', 'Baja la plataforma y sostén 2 segundos abajo antes de empujar.', 'Lower the platform and hold for 2 seconds at the bottom before pushing.'),
('leg_press_partial', 'legs', 'reps_weight', 4.5, NULL, 15, 2, 1.0, false, 'Prensa en recorrido parcial', 'Partial leg press', 'Haz repeticiones cortas en la mitad superior del recorrido, sin bloquear las rodillas.', 'Do short reps in the top half of the range, without locking your knees.'),
('leg_press_tempo', 'legs', 'reps_weight', 5.0, NULL, 10, 6, 0.8, false, 'Prensa con bajada lenta', 'Tempo leg press', 'Baja en 3–4 segundos y empuja en 1 segundo.', 'Lower in 3–4 seconds and push in 1 second.'),
('leg_press_pulse', 'legs', 'reps_weight', 4.5, NULL, 20, 2, 0.8, false, 'Prensa con rebotes', 'Leg press pulses', 'En la parte baja del recorrido, haz pequeños rebotes controlados.', 'At the bottom of the range, do small controlled pulses.'),
('leg_press_heavy', 'legs', 'reps_weight', 6.0, NULL, 6, 4, 1.4, false, 'Prensa pesada', 'Heavy leg press', 'Pocas repeticiones con carga alta, cuidando de no despegar la cadera del asiento.', 'Few reps with a heavy load, keeping your hips on the seat.'),
('leg_press_endurance', 'legs', 'reps_weight', 5.0, NULL, 25, 2, 0.6, false, 'Prensa de resistencia', 'Endurance leg press', 'Muchas repeticiones con carga liviana a ritmo constante.', 'Many reps with a light load at a steady pace.'),
('single_leg_press_glute', 'glutes', 'reps_weight', 5.0, NULL, 10, 3, 0.5, false, 'Prensa a una pierna para glúteo', 'Single-leg glute press', 'Con un pie alto en la plataforma, empuja desde el talón. Cambia de pierna.', 'With one foot high on the platform, push through the heel. Switch legs.'),
('leg_press_sumo', 'glutes', 'reps_weight', 5.0, NULL, 12, 3, 1.0, false, 'Prensa sumo', 'Sumo leg press', 'Pies muy abiertos y altos con las puntas afuera; baja profundo y empuja.', 'Feet very wide and high with toes out; lower deep and push.'),
('leg_press_single_calf', 'legs', 'reps_weight', 3.5, NULL, 15, 2, 0.5, false, 'Gemelo a una pierna en prensa', 'Single-leg press calf raise', 'Empuja con la punta de un solo pie con la pierna estirada. Cambia de lado.', 'Push with the ball of one foot with a straight leg. Switch sides.'),
('leg_press_eccentric', 'legs', 'reps_weight', 5.0, NULL, 8, 6, 1.0, false, 'Prensa excéntrica', 'Eccentric leg press', 'Empuja con las dos piernas y baja con una sola, lentamente. Alterna.', 'Push with both legs and lower slowly with one. Alternate.'),
('leg_press_drop_set', 'legs', 'reps_weight', 6.0, NULL, 10, 3, 0.9, false, 'Prensa con series descendentes', 'Leg press drop set', 'Al llegar al fallo, baja el peso y sigue sin descansar dos veces más.', 'When you reach failure, lower the weight and keep going without rest twice more.'),
('leg_press_wide_pause', 'glutes', 'reps_weight', 5.0, NULL, 10, 5, 0.9, false, 'Prensa abierta con pausa', 'Wide paused leg press', 'Pies abiertos; sostén 2 segundos abajo antes de empujar.', 'Wide feet; hold for 2 seconds at the bottom before pushing.'),
('leg_press_isometric', 'legs', 'time', 4.0, 0.5, NULL, 3, NULL, false, 'Isometría en prensa', 'Leg press isometric hold', 'Sostén la plataforma con las rodillas a 90° sin moverte.', 'Hold the platform with your knees at 90° without moving.'),
('rope_basic_bounce', 'general', 'time', 10.0, 5, NULL, 3, NULL, true, 'Soga: salto básico', 'Jump rope: basic bounce', 'Salta con los pies juntos, apenas despegando del suelo, girando la soga con las muñecas.', 'Jump with your feet together, barely leaving the floor, turning the rope with your wrists.'),
('rope_alternate_foot', 'general', 'time', 10.5, 5, NULL, 3, NULL, true, 'Soga: pie alternado', 'Jump rope: alternate foot', 'Salta alternando los pies como si trotaras en el lugar.', 'Jump alternating your feet as if jogging in place.'),
('rope_high_knees', 'general', 'time', 12.0, 3, NULL, 3, NULL, true, 'Soga: rodillas arriba', 'Jump rope: high knees', 'Salta elevando las rodillas hasta la cadera en cada vuelta.', 'Jump raising your knees to hip height on every turn.'),
('rope_double_unders', 'general', 'time', 12.5, 3, NULL, 3, NULL, true, 'Soga: doble salto', 'Jump rope: double-unders', 'Salta más alto y gira la soga dos veces por cada salto. Avanzado.', 'Jump higher and spin the rope twice per jump. Advanced.'),
('rope_criss_cross', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: cruzado', 'Jump rope: criss-cross', 'Cruza los brazos delante del cuerpo en una vuelta y descrúzalos en la siguiente.', 'Cross your arms in front of your body on one turn and uncross them on the next.'),
('rope_side_swing', 'general', 'time', 9.5, 4, NULL, 3, NULL, true, 'Soga: balanceo lateral', 'Jump rope: side swing', 'Alterna un salto con un balanceo de la soga al costado del cuerpo sin saltar.', 'Alternate a jump with a swing of the rope to the side of your body without jumping.'),
('rope_boxer_step', 'general', 'time', 10.0, 5, NULL, 3, NULL, true, 'Soga: paso de boxeador', 'Jump rope: boxer step', 'Pasa el peso de un pie al otro con pequeños rebotes, como un boxeador.', 'Shift your weight from one foot to the other with small bounces, like a boxer.'),
('rope_single_leg', 'legs', 'time', 11.0, 3, NULL, 3, NULL, true, 'Soga: a una pierna', 'Jump rope: single leg', 'Salta varias veces sobre un pie y luego cambia.', 'Jump several times on one foot, then switch.'),
('rope_side_to_side', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: lado a lado', 'Jump rope: side to side', 'Salta con los pies juntos de un lado al otro de una línea imaginaria.', 'Jump with your feet together from side to side over an imaginary line.'),
('rope_forward_backward', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: adelante y atrás', 'Jump rope: forward and backward', 'Salta con los pies juntos alternando un salto hacia adelante y uno hacia atrás.', 'Jump with your feet together alternating a hop forward and a hop back.'),
('rope_heel_toe', 'general', 'time', 10.0, 4, NULL, 3, NULL, true, 'Soga: talón y punta', 'Jump rope: heel-toe', 'Alterna tocar el suelo con el talón y con la punta de un pie entre saltos.', 'Alternate tapping the floor with one heel and then the toe between jumps.'),
('rope_jumping_jacks', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: tijeras', 'Jump rope: jumping jacks', 'Abre y cierra las piernas en cada salto mientras giras la soga.', 'Open and close your legs on each jump while turning the rope.'),
('rope_sprint_intervals', 'general', 'time', 12.5, 6, NULL, 3, NULL, true, 'Soga: intervalos rápidos', 'Jump rope sprint intervals', 'Haz 30 segundos lo más rápido posible y 30 segundos suaves, repitiendo.', 'Do 30 seconds as fast as possible and 30 easy seconds, repeating.'),
('rope_tabata', 'general', 'time', 12.0, 4, NULL, 3, NULL, true, 'Soga Tabata', 'Jump rope Tabata', 'Ocho rondas de 20 segundos al máximo con 10 segundos de pausa.', 'Eight rounds of 20 seconds all-out with 10 seconds of rest.'),
('rope_slow_endurance', 'general', 'time', 8.8, 10, NULL, 3, NULL, true, 'Soga lenta de resistencia', 'Slow endurance jump rope', 'Salta a ritmo lento y constante el mayor tiempo posible sin cortar.', 'Jump at a slow, steady pace for as long as you can without stopping.'),
('rope_warm_up', 'general', 'time', 8.0, 3, NULL, 3, NULL, true, 'Soga: entrada en calor', 'Jump rope warm-up', 'Saltos suaves y cortos para preparar tobillos y pantorrillas.', 'Light, short jumps to prepare your ankles and calves.'),
('rope_skier', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: esquiador', 'Jump rope: skier', 'Salta con los pies juntos de lado a lado como un esquiador.', 'Jump with your feet together from side to side like a skier.'),
('rope_bell', 'general', 'time', 11.0, 4, NULL, 3, NULL, true, 'Soga: campana', 'Jump rope: bell jumps', 'Salta con los pies juntos hacia adelante y hacia atrás como el badajo de una campana.', 'Jump with your feet together forward and back like a bell clapper.'),
('rope_backward', 'general', 'time', 10.5, 4, NULL, 3, NULL, true, 'Soga hacia atrás', 'Backward jump rope', 'Gira la soga hacia atrás y salta con los pies juntos.', 'Turn the rope backward and jump with your feet together.'),
('rope_combo', 'general', 'time', 11.5, 6, NULL, 3, NULL, true, 'Soga: combinado', 'Jump rope combo', 'Combina básico, alternado, tijeras y cruzado cambiando cada 30 segundos.', 'Combine basic, alternate, jacks and criss-cross switching every 30 seconds.'),
('ball_crunch', 'abs', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Crunch en fitball', 'Stability ball crunch', 'Con la zona lumbar apoyada en la pelota, eleva el torso contrayendo el abdomen y baja despacio.', 'With your lower back on the ball, lift your torso by contracting your abs and lower slowly.'),
('ball_pike', 'abs', 'reps', 4.0, NULL, 8, 4, NULL, false, 'Pica en fitball', 'Stability ball pike', 'En plancha alta con los pies sobre la pelota, eleva la cadera llevando la pelota hacia las manos.', 'In a high plank with your feet on the ball, raise your hips rolling the ball toward your hands.'),
('ball_rollout', 'abs', 'reps', 3.5, NULL, 10, 4, NULL, false, 'Rodamiento en fitball', 'Stability ball rollout', 'De rodillas con los antebrazos sobre la pelota, ruédala al frente estirando el cuerpo y vuelve.', 'Kneeling with your forearms on the ball, roll it forward extending your body and return.'),
('ball_plank', 'abs', 'time', 3.8, 0.75, NULL, 3, NULL, false, 'Plancha en fitball', 'Stability ball plank', 'Apoya los antebrazos en la pelota y mantén el cuerpo recto sin que la pelota se mueva.', 'Rest your forearms on the ball and keep your body straight without letting the ball move.'),
('ball_knee_tuck', 'abs', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Encogimiento de rodillas en fitball', 'Stability ball knee tuck', 'En plancha alta con las canillas sobre la pelota, lleva las rodillas al pecho y vuelve.', 'In a high plank with your shins on the ball, pull your knees to your chest and return.'),
('ball_v_pass', 'abs', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Pase de fitball manos-pies', 'Stability ball V-pass', 'Acostado, pasa la pelota de las manos a los pies subiendo brazos y piernas a la vez, y viceversa.', 'Lying down, pass the ball from your hands to your feet by lifting arms and legs together, and back.'),
('ball_back_extension', 'back', 'reps', 3.0, NULL, 12, 3, NULL, false, 'Extensión de espalda en fitball', 'Stability ball back extension', 'Boca abajo con la cadera sobre la pelota y los pies apoyados, eleva el torso y baja.', 'Face down with your hips on the ball and feet on the floor, lift your torso and lower.'),
('ball_hamstring_curl', 'glutes', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Curl femoral en fitball', 'Stability ball hamstring curl', 'Acostado con los talones sobre la pelota y la cadera arriba, flexiona las rodillas acercando la pelota.', 'Lying with your heels on the ball and hips up, bend your knees to roll the ball in.'),
('ball_glute_bridge', 'glutes', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Puente de glúteos con pies en fitball', 'Stability ball glute bridge', 'Con los pies sobre la pelota, eleva la cadera apretando los glúteos y baja.', 'With your feet on the ball, lift your hips squeezing your glutes and lower.'),
('ball_wall_squat', 'legs', 'reps', 4.0, NULL, 15, 3, NULL, false, 'Sentadilla con fitball en la pared', 'Stability ball wall squat', 'Con la pelota entre la espalda baja y la pared, baja en sentadilla rodándola y sube.', 'With the ball between your lower back and the wall, squat down rolling it and stand back up.'),
('ball_push_up', 'chest', 'reps', 3.8, NULL, 10, 3, NULL, false, 'Flexiones con manos en fitball', 'Stability ball push-up', 'Con las manos sobre la pelota y el cuerpo recto, baja el pecho y empuja manteniendo el equilibrio.', 'With your hands on the ball and body straight, lower your chest and push up while keeping balance.'),
('ball_decline_push_up', 'chest', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Flexiones con pies en fitball', 'Stability ball decline push-up', 'Con los pies sobre la pelota y las manos en el suelo, baja el pecho y empuja.', 'With your feet on the ball and hands on the floor, lower your chest and push up.'),
('ball_side_crunch', 'abs', 'reps', 3.0, NULL, 12, 3, NULL, false, 'Crunch lateral en fitball', 'Stability ball side crunch', 'De costado sobre la pelota con los pies apoyados, eleva el torso hacia el techo. Cambia de lado.', 'Lying sideways over the ball with your feet braced, lift your torso toward the ceiling. Switch sides.'),
('ball_russian_twist', 'abs', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Giro ruso en fitball', 'Stability ball Russian twist', 'Con la espalda alta sobre la pelota y la cadera arriba, gira el torso con los brazos estirados de lado a lado.', 'With your upper back on the ball and hips up, rotate your torso side to side with straight arms.'),
('ball_hip_thrust', 'glutes', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Hip thrust con espalda en fitball', 'Stability ball hip thrust', 'Con la espalda alta sobre la pelota, baja la cadera y súbela hasta alinearla con el torso.', 'With your upper back on the ball, lower your hips and drive them up until aligned with your torso.'),
('ball_reverse_hyper', 'glutes', 'reps', 3.0, NULL, 12, 3, NULL, false, 'Hiperextensión inversa en fitball', 'Stability ball reverse hyperextension', 'Boca abajo con la cadera sobre la pelota y las manos en el suelo, eleva las piernas estiradas.', 'Face down with your hips on the ball and hands on the floor, lift your straight legs.'),
('ball_seated_balance', 'abs', 'time', 2.5, 2, NULL, 3, NULL, false, 'Equilibrio sentado en fitball', 'Stability ball seated balance', 'Sentado en la pelota, eleva un pie y mantén el equilibrio con el abdomen firme. Alterna.', 'Seated on the ball, lift one foot and keep your balance with tight abs. Alternate.'),
('ball_dead_bug', 'abs', 'reps', 3.0, NULL, 12, 3, NULL, false, 'Dead bug con fitball', 'Stability ball dead bug', 'Acostado sosteniendo la pelota entre manos y rodillas, extiende un brazo y la pierna contraria. Alterna.', 'Lying down holding the ball between hands and knees, extend one arm and the opposite leg. Alternate.'),
('ball_mountain_climber', 'abs', 'time', 6.5, 1.5, NULL, 3, NULL, true, 'Escaladores con manos en fitball', 'Stability ball mountain climbers', 'Con las manos sobre la pelota y el cuerpo recto, lleva las rodillas al pecho alternando.', 'With your hands on the ball and body straight, drive your knees to your chest alternating.'),
('ball_chest_press', 'chest', 'reps', 3.0, NULL, 15, 3, NULL, false, 'Puente en fitball con brazos al techo', 'Stability ball bridge reach', 'Con la espalda alta en la pelota y la cadera arriba, extiende los brazos hacia el techo y bájalos despacio.', 'With your upper back on the ball and hips up, reach your arms to the ceiling and lower them slowly.'),
('mb_slam', 'general', 'reps', 8.0, NULL, 12, 2, NULL, true, 'Lanzamiento de pelota medicinal al suelo', 'Medicine ball slam', 'Eleva la pelota sobre la cabeza y lánzala con fuerza contra el suelo flexionando la cadera.', 'Lift the ball overhead and slam it hard into the floor by hinging at the hips.'),
('mb_chest_pass', 'chest', 'reps', 6.0, NULL, 12, 2, NULL, false, 'Pase de pecho con pelota medicinal', 'Medicine ball chest pass', 'Lanza la pelota desde el pecho contra una pared o compañero estirando los brazos de golpe.', 'Throw the ball from your chest against a wall or partner by straightening your arms explosively.'),
('mb_overhead_throw', 'shoulders', 'reps', 6.5, NULL, 10, 2, NULL, false, 'Lanzamiento sobre la cabeza', 'Medicine ball overhead throw', 'Lleva la pelota detrás de la cabeza y lánzala hacia adelante con ambos brazos.', 'Bring the ball behind your head and throw it forward with both arms.'),
('mb_wall_ball', 'legs', 'reps', 8.0, NULL, 12, 3, NULL, true, 'Wall ball', 'Wall ball', 'Baja en sentadilla con la pelota en el pecho y, al subir, lánzala hacia un punto alto de la pared.', 'Squat with the ball at your chest and, as you stand, throw it to a high spot on the wall.'),
('mb_russian_twist', 'abs', 'reps', 4.0, NULL, 16, 2, NULL, false, 'Giro ruso con pelota medicinal', 'Medicine ball Russian twist', 'Sentado con el torso inclinado atrás, lleva la pelota de un lado al otro de la cadera.', 'Seated with your torso leaning back, move the ball from one side of your hips to the other.'),
('mb_squat', 'legs', 'reps', 5.0, NULL, 15, 3, NULL, false, 'Sentadilla con pelota medicinal', 'Medicine ball squat', 'Sostén la pelota frente al pecho y baja en sentadilla con el torso erguido.', 'Hold the ball in front of your chest and squat with an upright torso.'),
('mb_lunge_twist', 'legs', 'reps', 5.0, NULL, 10, 3, NULL, false, 'Estocada con giro y pelota medicinal', 'Medicine ball lunge with twist', 'Da una estocada al frente y, abajo, gira el torso hacia la pierna de adelante con la pelota.', 'Lunge forward and, at the bottom, rotate your torso toward the front leg holding the ball.'),
('mb_v_up', 'abs', 'reps', 4.5, NULL, 10, 3, NULL, false, 'V-up con pelota medicinal', 'Medicine ball V-up', 'Acostado con la pelota sobre la cabeza, sube brazos y piernas a la vez hasta tocar los pies con la pelota.', 'Lying with the ball overhead, raise your arms and legs together until the ball touches your feet.'),
('mb_sit_up_throw', 'abs', 'reps', 5.0, NULL, 10, 3, NULL, false, 'Abdominal con lanzamiento', 'Medicine ball sit-up throw', 'Acostado con la pelota sobre el pecho, sube al abdominal y lánzala contra la pared o a un compañero.', 'Lying with the ball on your chest, sit up and throw it against a wall or to a partner.'),
('mb_woodchop', 'abs', 'reps', 5.0, NULL, 12, 3, NULL, false, 'Leñador con pelota medicinal', 'Medicine ball woodchop', 'Lleva la pelota desde arriba de un hombro hacia la rodilla contraria girando el torso.', 'Bring the ball from above one shoulder down to the opposite knee while rotating your torso.'),
('mb_overhead_lunge', 'legs', 'reps', 5.0, NULL, 10, 3, NULL, false, 'Estocada con pelota sobre la cabeza', 'Overhead medicine ball lunge', 'Con la pelota arriba y los brazos estirados, da estocadas manteniendo el torso erguido.', 'With the ball overhead and arms straight, lunge while keeping your torso upright.'),
('mb_push_up', 'chest', 'reps', 4.0, NULL, 10, 3, NULL, false, 'Flexiones con una mano en pelota medicinal', 'Medicine ball push-up', 'Con una mano sobre la pelota y la otra en el suelo, haz la flexión. Cambia de lado.', 'With one hand on the ball and the other on the floor, do the push-up. Switch sides.'),
('mb_side_throw', 'abs', 'reps', 6.0, NULL, 10, 2, NULL, false, 'Lanzamiento lateral rotacional', 'Medicine ball rotational throw', 'De costado a la pared, gira el torso y lanza la pelota con fuerza contra ella. Cambia de lado.', 'Standing sideways to the wall, rotate your torso and throw the ball hard against it. Switch sides.'),
('mb_burpee', 'general', 'reps', 9.0, NULL, 8, 4, NULL, true, 'Burpee con pelota medicinal', 'Medicine ball burpee', 'Apoya las manos en la pelota, lleva los pies atrás, vuelve y salta elevando la pelota sobre la cabeza.', 'Place your hands on the ball, jump your feet back, return and jump lifting the ball overhead.'),
('mb_deadlift', 'glutes', 'reps', 4.5, NULL, 15, 3, NULL, false, 'Peso muerto con pelota medicinal', 'Medicine ball deadlift', 'Con la pelota en el suelo entre los pies, tómala con la espalda recta y levántate.', 'With the ball on the floor between your feet, grab it with a straight back and stand up.'),
('mb_good_morning', 'glutes', 'reps', 3.5, NULL, 15, 3, NULL, false, 'Buenos días con pelota medicinal', 'Medicine ball good morning', 'Con la pelota contra el pecho, inclina el torso llevando la cadera atrás y vuelve.', 'Holding the ball against your chest, hinge forward pushing your hips back and return.'),
('mb_front_raise', 'shoulders', 'reps', 3.5, NULL, 12, 3, NULL, false, 'Elevación frontal con pelota medicinal', 'Medicine ball front raise', 'Con los brazos estirados, eleva la pelota al frente hasta la altura de los hombros y baja.', 'With straight arms, raise the ball in front of you to shoulder height and lower.'),
('mb_overhead_squat', 'legs', 'reps', 5.5, NULL, 12, 3, NULL, false, 'Sentadilla con pelota sobre la cabeza', 'Overhead medicine ball squat', 'Con la pelota arriba y los brazos estirados, baja en sentadilla manteniendo el torso erguido.', 'With the ball overhead and arms straight, squat while keeping your torso upright.'),
('mb_halo', 'shoulders', 'reps', 3.5, NULL, 10, 4, NULL, false, 'Halo con pelota medicinal', 'Medicine ball halo', 'Haz girar la pelota alrededor de la cabeza con ambas manos, en ambos sentidos.', 'Circle the ball around your head with both hands, in both directions.'),
('mb_toe_taps', 'general', 'time', 7.0, 2, NULL, 3, NULL, true, 'Toques de punta sobre la pelota', 'Medicine ball toe taps', 'Con la pelota en el suelo, toca la parte de arriba con la punta de un pie y alterna rápido.', 'With the ball on the floor, tap the top with the ball of one foot and alternate quickly.')
